def compare(n: str, bound: str) -> bool:
    """Compare if n is less than or equal to bound"""
    if len(n) < len(bound):
        return True
    if len(n) > len(bound):
        return False
    # Same length, compare lexicographically
    return n <= bound

n = input().strip()

if compare(n, "127"):
    print("byte")
elif compare(n, "32767"):
    print("short")
elif compare(n, "2147483647"):
    print("int")
elif compare(n, "9223372036854775807"):
    print("long")
else:
    print("BigInteger")
"}

