import sys

def solve():
    MOD = 10**9 + 7
    t = int(sys.stdin.readline())

    for _ in range(t):
        n_str, m = sys.stdin.readline().split()
        m = int(m)

        # Compute dp for all digits and operations
        dp = [[0] * (m + 1) for _ in range(10)]

        # Base case: after 0 operations
        for digit in range(10):
            dp[digit][0] = 1

        # Fill dp table
        for op in range(1, m + 1):
            for digit in range(10):
                if digit < 9:
                    # Current digit becomes digit+1
                    dp[digit][op] = dp[digit + 1][op - 1]
                else:
                    # Current digit becomes 10, which becomes "21"
                    # So we need to consider both digits '0' and '1'
                    dp[digit][op] = (dp[0][op - 1] + dp[1][op - 1]) % MOD

        # Sum lengths for all digits in n
        total_length = 0
        for c in n_str:
            d = int(c)
            total_length = (total_length + dp[d][m]) % MOD

        print(total_length)

if __name__ == "__main__":
    solve()
"}

