import sys
from itertools import permutations

def is_divisible_by_7(s):
    """Check if a string representation of a number is divisible by 7"""
    return int(s) % 7 == 0

def solve(a):
    digits = list(a)

    # Try all permutations
    for perm in permutations(digits):
        # Skip leading zeroes
        if perm[0] == '0':
            continue

        # Check divisibility by 7
        if is_divisible_by_7(''.join(perm)):
            return ''.join(perm)

    return '0'

if __name__ == '__main__':
    a = sys.stdin.readline().strip()
    result = solve(a)
    sys.stdout.write(result)
"}

