import sys

def solve(a):
    # Check if the original number works
    if int(a) % 7 == 0:
        return a

    # Try to find a valid permutation
    n = len(a)
    digits = list(a)

    # Try all permutations (this is still inefficient for large n)
    # But maybe we can just try a few simple swaps for now

    # Try swapping different positions
    for i in range(n):
        for j in range(i + 1, n):
            # Swap digits at positions i and j
            digits[i], digits[j] = digits[j], digits[i]

            # Check for leading zero
            if digits[0] != '0':
                num = int(''.join(digits))
                if num % 7 == 0:
                    return ''.join(digits)

            # Swap back
            digits[i], digits[j] = digits[j], digits[i]

    return '0'

if __name__ == '__main__':
    a = sys.stdin.readline().strip()
    result = solve(a)
    sys.stdout.write(result)
"}

