def longest_common_subsequence_without_virus(s1, s2, virus):
    """Find the longest common subsequence of s1 and s2 that doesn't contain virus as a substring."""

    # Step 1: Find the LCS using dynamic programming
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table for LCS length
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Step 2: Reconstruct the LCS
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if s1[i-1] == s2[j-1]:
            lcs.append(s1[i-1])
            i -= 1
            j -= 1
        else:
            if dp[i-1][j] > dp[i][j-1]:
                i -= 1
            else:
                j -= 1

    lcs.reverse()

    # Step 3: Check if the LCS contains virus as a substring
    if virus in ''.join(lcs):
        # If it does, try to find a different LCS
        # We need to find the longest valid LCS
        # This is more complex - we need to try different paths
        # Let me use backtracking to find all possible LCS and pick the valid one

        # Backtrack to find all LCS
        paths = []
        i, j = m, n

        def backtrack(i, j, path):
            if i == 0 or j == 0:
                paths.append(''.join(path))
                return

            if s1[i-1] == s2[j-1]:
                path.append(s1[i-1])
                backtrack(i-1, j-1, path)
                path.pop()
            else:
                if dp[i-1][j] > dp[i][j-1]:
                    backtrack(i-1, j, path)
                else:
                    backtrack(i, j-1, path)

        backtrack(m, n, [])

        # Find the longest valid LCS
        paths = [path for path in paths if virus not in path]
        if paths:
            return max(paths, key=len)
        else:
            return 0
    else:
        return ''.join(lcs)

