def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # Count occurrences of each value after each position
        count_after = [{} for _ in range(n+1)]
        for i in range(n-1, -1, -1):
            for key, val in count_after[i+1].items():
                count_after[i][key] = val
            count_after[i][a[i]] = count_after[i].get(a[i], 0) + 1

        result = 0
        # Try all pairs (i, k) where i < k and a[i] = a[k]
        for i in range(n):
            for k in range(i+1, n):
                if a[i] == a[k]:
                    # Count how many times each value appears in (i+1, k-1)
                    cnt_in_between = {}
                    for j in range(i+1, k):
                        cnt_in_between[a[j]] = cnt_in_between.get(a[j], 0) + 1

                    # For each value, multiply by how many times it appears after k
                    for val, cnt in cnt_in_between.items():
                        result += cnt * count_after[k][val]

        print(result)

