def solve():
    s = input().strip()
    n = len(s)

    # dp[l][r][k] = True if substring s[l:r+1] is a k-palindrome
    dp = [[[False] * (n + 1) for _ in range(n + 1)] for _ in range(n + 1)]

    # Base case: 1-palindromes
    for l in range(n):
        for r in range(n):
            if s[l] == s[r]:
                dp[l][r][1] = True

    # Check for k-palindromes
    for length in range(2, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            # Check if it's a palindrome
            if dp[l][r][1]:
                # Check if it's a k-palindrome
                for k in range(2, n + 1):
                    if length % 2 == 0:
                        half_len = length // 2
                        left_l = l
                        left_r = l + half_len - 1
                        right_l = r - half_len + 1
                        right_r = r
                    else:
                        half_len = length // 2
                        left_l = l
                        left_r = l + half_len - 1
                        right_l = r - half_len + 1
                        right_r = r

                    if dp[left_l][left_r][k-1] and dp[right_l][right_r][k-1]:
                        dp[l][r][k] = True

    # Count k-palindromes
    result = [0] * n
    for k in range(1, n + 1):
        count = 0
        for l in range(n):
            for r in range(n):
                if dp[l][r][k]:
                    count += 1
        result[k-1] = count

    print(' '.join(map(str, result)))

solve()
