{"code": "
def count_special_matrices(n, m, mod):
    # Read the given rows
    given_rows = []
    for _ in range(m):
        row = input().strip()
        given_rows.append(row)

    # Check if given rows are valid
    col_counts = [0] * n
    for i in range(n):
        ones = sum(1 for j in range(n) if given_rows[i][j] == '1')
        if ones != 2:
            return 0

        for j in range(n):
            if given_rows[i][j] == '1':
                col_counts[j] += 1
                if col_counts[j] > 2:
                    return 0

    # DP: dp[col_counts] = number of ways
    from functools import lru_cache

    # Convert column counts to a tuple for hashing
    initial_col_counts = tuple(col_counts)

    @lru_cache(maxsize=None)
    def dp(col_counts, rows_left):
        if rows_left == 0:
            return 1

        total = 0

        # Try all possible row configurations (which columns to place ones)
        for mask in range(1 << n):
            ones = bin(mask).count('1')
            if ones != 2:
                continue

            valid = True
            for j in range(n):
                if (mask >> j) & 1:
                    if col_counts[j] == 0:
                        valid = False
                        break

            if not valid:
                continue

            # Create new column counts
            new_col_counts = list(col_counts)
            for j in range(n):
                if (mask >> j) & 1:
                    new_col_counts[j] -= 1

            total += dp(tuple(new_col_counts), rows_left - 1)

        return total

    return dp(initial_col_counts, n - m)

n, m, mod = map(int, input().split())
result = count_special_matrices(n, m, mod)
print(result % mod)
