def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # dp[i][j] = minimum possible length of subarray from i to j
    dp = [[0] * n for _ in range(n)]

    # Base case: single element
    for i in range(n):
        dp[i][i] = 1

    # Fill dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1

            # If first and last elements are equal, try to merge
            if a[i] == a[j]:
                dp[i][j] = dp[i][j-1]
                # Try all splits
                for k in range(i, j):
                    if a[k] == a[j]:
                        dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j] - 1)
            else:
                # Cannot merge directly, try all splits
                for k in range(i, j):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j])

    print(dp[0][n-1])

solve()
