{"code": "
n, m = map(int, input().split())
grid = [list(input().strip()) for _ in range(n)]

# Mark cells as covered
covered = [[False] * m for _ in range(n)]
stars = []

for i in range(n):
    for j in range(m):
        if grid[i][j] == '*' and not covered[i][j]:
            # Try to cover this star
            found = False
            for s in range(1, min(i + 1, n - i, j + 1, m - j) + 1):
                # Star at (i, j) with size s covers:
                # (i-s, j), (i+s, j), (i, j-s), (i, j+s), (i, j)
                covered_cells = set()
                for di, dj in [(-s, 0), (s, 0), (0, -s), (0, s), (0, 0)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        covered_cells.add((ni, nj))

                # Check if all covered cells are '*' and not already covered
                all_valid = True
                for (ni, nj) in covered_cells:
                    if grid[ni][nj] != '*' or covered[ni][nj]:
                        all_valid = False
                        break

                if all_valid:
                    # Mark these cells as covered
                    for (ni, nj) in covered_cells:
                        covered[ni][nj] = True
                    stars.append((i + 1, j + 1, s))  # Convert to 1-indexed
                    found = True
                    break

            if not found:
                print(-1)
                exit()

print(len(stars))
for star in stars:
    print(star[0], star[1], star[2])
