def movement_time(from_c, to_c):
    if from_c == to_c:
        return 0
    if from_c == 1 and to_c == 2:
        return 1
    if from_c == 1 and to_c == 3:
        return 2
    if from_c == 2 and to_c == 1:
        return 2
    if from_c == 2 and to_c == 3:
        return 1
    if from_c == 3 and to_c == 1:
        return 1
    if from_c == 3 and to_c == 2:
        return 2
    return float('inf')

def solve():
    n = int(input())
    computers = list(map(int, input().split()))

    # Build adjacency list for dependencies
    dependencies = [[] for _ in range(n)]
    for i in range(n):
        parts = list(map(int, input().split()))
        ki = parts[0]
        if ki > 0:
            dependencies[i] = [parts[j] - 1 for j in range(1, ki + 1)]  # 0-indexed

    # Process in topological order (reverse post-order traversal)
    # First, find topological order using DFS
    visited = [False] * n
    order = []

    def dfs(u):
        visited[u] = True
        for v in dependencies[u]:
            if not visited[v]:
                dfs(v)
        order.append(u)

    for i in range(n):
        if not visited[i]:
            dfs(i)

    # Now order contains parts in topological order

    # DP: dp[i][c] = minimum time to complete parts up to i (in order) starting from computer c
    # Since dependencies must be completed before a part, we process in topological order
    INF = float('inf')
    dp = [[INF] * 4 for _ in range(n)]  # computers 1, 2, 3

    # Base case: just the first part in topological order
    first = order[0]
    for c in range(1, 4):
        dp[first][c] = movement_time(c, computers[first]) + 1

    # Process remaining parts
    for i in range(1, n):
        current = order[i]
        prev = order[i - 1]

        # To complete current part, we need to be on computer c_current
        # We can come from any previous state (dp[prev][c])
        for c in range(1, 4):
            # Time to get from computer c to computer of current part
            time_to_current = movement_time(c, computers[current])
            if time_to_current == INF:
                continue

            # Time to complete current part
            total = time_to_current + 1

            # Add time from all dependencies
            for dep in dependencies[current]:
                if dp[dep][c] == INF:
                    continue
                total += dp[dep][c]

            dp[current][c] = min(dp[current][c], total)

    # Find the minimum time starting from any computer
    result = min(dp[first][1], dp[first][2], dp[first][3])
    print(result)

solve()
