def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())

        # Read the 3 rows
        rows = []
        for _ in range(3):
            row = input().strip()
            rows.append(row)

        # Find Philip's starting position
        start_col = 0
        start_row = -1
        for i in range(3):
            if 's' in rows[i]:
                start_row = i
                break

        # Find train positions
        trains = []
        for i in range(3):
            row = rows[i]
            for j in range(n):
                if row[j] != '.' and row[j] != 's':
                    trains.append((i, j))

        # Simulate
        col = start_col
        row = start_row

        while col < n - 1:
            # Philip moves right
            col += 1

            # Check if out of bounds or collision
            if col >= n or col < 0 or row < 0 or row >= 3:
                print("NO")
                break

            # Check collision with trains
            colliding = False
            for (train_row, train_col) in trains:
                if train_row == row and train_col == col:
                    colliding = True
                    break

            if colliding:
                print("NO")
                break

            # Philip moves up/down or stays
            # We'll try all possibilities
            for move in [-1, 0, 1]:
                new_row = row + move

                # Check if new position is valid
                if new_row < 0 or new_row >= 3:
                    continue

                # Check if collision with trains (after moving right)
                colliding = False
                for (train_row, train_col) in trains:
                    if train_row == new_row and train_col == col:
                        colliding = True
                        break

                if colliding:
                    continue

                # Update position
                row = new_row

                # Trains move left twice
                for _ in range(2):
                    for i in range(len(trains)):
                        trains[i] = (trains[i][0], trains[i][1] - 1)

                # Check if any train has left the tunnel
                for i in range(len(trains)):
                    if trains[i][1] < 0:
                        trains.pop(i)
                        break

                # Check if any train has collided with Philip
                colliding = False
                for (train_row, train_col) in trains:
                    if train_row == row and train_col == col:
                        colliding = True
                        break

                if colliding:
                    print("NO")
                    break
            else:
                # No valid move found
                print("NO")
                break
        else:
            # Philip reached the end
            print("YES")

