def solve():
    n = int(input())
    clubs = []

    for _ in range(n):
        team, hometown = input().split()
        option1 = team[:3]
        option2 = team[:2] + hometown[0]
        clubs.append((option1, option2))

    # Build graph: club -> neighbors (short names they can take)
    from collections import defaultdict
    adj = defaultdict(set)
    for i in range(n):
        opt1, opt2 = clubs[i]
        adj[i].add(opt1)
        adj[i].add(opt2)

    # Build conflict graph: short name -> set of clubs that cannot use it
    conflict = defaultdict(set)
    for i in range(n):
        opt1, opt2 = clubs[i]
        # If a club uses option1, no other club can use option1 for the same short name
        conflict[opt1].add(i)
        # If a club uses option2, no club can use option1 for the same short name as this club's option1
        conflict[opt1].add(i)

    # Build bipartite graph: clubs on left, short names on right
    # Edge from club i to short name s if club i can take s without conflict

    # Create graph for matching
    from collections import deque

    # Augmenting path algorithm
    match_to = {}
    visited = set()

    def bpm(u):
        if u not in visited:
            visited.add(u)
            for v in adj[u]:
                # Check if this short name is available
                if v not in match_to:
                    match_to[v] = u
                    return True
                # Or if the matched club can be rematched
                if bpm(match_to[v]):
                    match_to[v] = u
                    return True
        return False

    # Try to find matching for each club
    for u in range(n):
        if bpm(u):
            pass

    # Check if all clubs are matched
    if len(match_to) == n:
        result = []
        for i in range(n):
            for opt in adj[i]:
                if opt in match_to and match_to[opt] == i:
                    result.append(opt)
                    break
        print("YES")
        for name in result:
