import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    size = 1 << n

    # Use a simple array representation
    arr = [0] * size
    for i in range(size):
        arr[i] = int(next(it))

    # Process queries
    for _ in range(q):
        cmd = next(it)
        if cmd == '1':
            # Replace(x, k)
            x = int(next(it)) - 1  # convert to 0-indexed
            k = int(next(it))
            arr[x] = k
        elif cmd == '2':
            # Reverse(k)
            k = int(next(it))
            length = 1 << k
            # Apply reverse to all subarrays of length 2^k
            for i in range(0, size - length + 1, 2 * length):
                # Reverse subarray [i, i+length-1] with [i+length, i+length*2-1]
                # We need to make sure the indices don't overflow
                if i + length * 2 - 1 < size:
                    for j in range(length):
                        arr[i+j], arr[i+length+j] = arr[i+length+j], arr[i+j]
        elif cmd == '3':
            # Swap(k)
            k = int(next(it))
            length = 1 << k
            for i in range(0, size - length + 1, 2 * length):
                # Swap subarray [i, i+length-1] with [i+length, i+length*2-1]
                if i + length * 2 - 1 < size:
                    for j in range(length):
                        arr[i+j], arr[i+length+j] = arr[i+length+j], arr[i+j]
        elif cmd == '4':
            # Sum(l, r)
            l = int(next(it)) - 1  # convert to 0-indexed
            r = int(next(it)) - 1
            # Compute sum of subarray [l, r]
            res = sum(arr[l:r+1])
            print(res)

