    if i == 0:
        x, y = x0, y0
    else:
        x = ax * x_prev + bx
        y = ay * y_prev + by
    nodes.append((x, y))
    x_prev, y_prev = x, y

    # Check if distance from start is too large
    if distance((x, y), (x_s, y_s)) > t:
        break

# Try all possible subsets of nodes to collect
max_collected = 0

from itertools import combinations

# Try all possible numbers of nodes to collect
for k in range(len(nodes), 0, -1):
    # Try all combinations of k nodes
    for indices in combinations(range(len(nodes)), k):
        # Try all possible orderings of these k nodes
        for perm in permutations([nodes[i] for i in indices]):
            collected = 0
            total_time = 0

            # Try collecting nodes in this order
            for i, (x, y) in enumerate(perm):
                if i == 0:
                    # Time to move from start to first node
                    total_time += distance((x, y), (x_s, y_s))
                else:
                    # Time to move from previous position to current node
                    total_time += distance((x, y), perm[i-1])

