n = int(input())
projects = {}

# Parse projects
for _ in range(n):
    # Skip empty lines
    while True:
        line = input().strip()
        if line:
            break
    name, version = line.split()
    version = int(version)

    # Read dependencies
    while True:
        line = input().strip()
        if line:
            break
    num_deps = int(line)

    dependencies = []
    for _ in range(num_deps):
        while True:
            line = input().strip()
            if line:
                break
        dep_name, dep_version = line.split()
        dep_version = int(dep_version)
        dependencies.append((dep_name, dep_version))

    projects[(name, version)] = dependencies

# Find Polycarp's project (first one)
polycarp = list(projects.keys())[0]

# Build graph (adjacency list)
graph = {}
for (name, version), deps in projects.items():
    for dep_name, dep_version in deps:
        if dep_name not in graph:
            graph[dep_name] = {}
        if name not in graph[dep_name]:
            graph[dep_name][name] = version
        else:
            # Multiple projects with the same name, keep the version
            graph[dep_name][name] = max(graph[dep_name][name], version)

# Find shortest distance from Polycarp's project using BFS
distances = {}
queue = [(polycarp[0], polycarp[1])]
distances[(polycarp[0], polycarp[1])] = 0

while queue:
    name, version = queue.pop(0)

    for dep_name, dep_version in projects[(name, version)]:
        dep_key = (dep_name, dep_version)
        if dep_key not in distances:
            distances[dep_key] = distances[(name, version)] + 1
            queue.append(dep_key)

# For each name, find the version with minimum distance (and maximum version in case of ties)
result = {}
for name, versions in projects.items():
    # Find the version with minimum distance
    min_distance = float('inf')
    chosen_version = -1

    for version in versions:
        key = (name, version)
        if key in distances:
            if distances[key] < min_distance or (distances[key] == min_distance and version > chosen_version):
                min_distance = distances[key]
                chosen_version = version

    if chosen_version != -1:
        result[name] = chosen_version

# Output in lexicographical order
for name in sorted(result.keys()):
    print(f"{name} {result[name]}")
