n = int(input())

clubs = []
for _ in range(n):
    team, hometown = input().split()
    option1 = team[:3]
    option2 = team[:2] + hometown[0]
    clubs.append((team, hometown, option1, option2))

# Group clubs by their Option 1 name
option1_to_clubs = {}
for i, (team, hometown, opt1, opt2) in enumerate(clubs):
    if opt1 not in option1_to_clubs:
        option1_to_clubs[opt1] = []
    option1_to_clubs[opt1].append((i, team, hometown, opt1, opt2))

# Check if it's possible
possible = True
assignment = [None] * n

# For each group of clubs with the same Option 1
for opt1, club_list in option1_to_clubs.items():
    # If there's only one club, we can use Option 1
    if len(club_list) == 1:
        i, _, _, _, opt2 = club_list[0]
        assignment[i] = opt1
    else:
        # There are multiple clubs with the same Option 1
        # We need to decide which ones use Option 1 and which use Option 2
        # We'll use Option 1 for the first club and Option 2 for the rest
        # But we need to ensure no conflicts
        first_i, _, _, _, first_opt2 = club_list[0]
        assignment[first_i] = opt1

        # Check if any of the remaining clubs can use Option 1
        for i, _, _, _, opt2 in club_list[1:]:
            if opt2 == opt1:
                # This club's Option 2 is the same as the Option 1 name
                # If we use Option 1 for this club, it would conflict with the first club's Option 2
                # So we need to use Option 2
                assignment[i] = opt2
            else:
                # Can this club use Option 1?
                # We need to check if any club that uses Option 2 has the same Option 1 as this club's Option 1
                # If not, we can use Option 1
                can_use_opt1 = True
                for j, _, _, _, opt1_j_opt2 in club_list:
                    if j == i:
                        continue
                    if opt1_j_opt2 == opt1:
                        can_use_opt1 = False
                        break

                if can_use_opt1:
                    assignment[i] = opt1
                else:
                    assignment[i] = opt2

# Verify all short names are distinct and constraints are satisfied
used = set()
valid = True

for i, (team, hometown, opt1, opt2) in enumerate(clubs):
    chosen = assignment[i]
    if chosen in used:
        valid = False
        break
    used.add(chosen)

if not valid:
    print("NO")
else:
    print("YES")
    for name in assignment:
        print(name)
