def solve():
    n, m, k = map(int, input().split())

    # Read planets
    planets = []
    for _ in range(n):
        name = input().strip()
        items = []
        for _ in range(m):
            a, b, c = map(int, input().split())
            items.append((a, b, c))
        planets.append((name, items))

    # Find all profitable item pairs
    items = []
    for buy_planet in range(n):
        for sell_planet in range(n):
            if buy_planet == sell_planet:
                continue  # Can't buy and sell on the same planet

            for j in range(m):
                a, b, c = planets[buy_planet][1][j]
                profit = b - a
                if profit > 0:
                    # Add this item to the knapsack
                    items.append((profit, 1, min(c, k)))  # value, weight, quantity

    # 0/1 knapsack with capacity k
    dp = [0] * (k + 1)

    for value, weight, quantity in items:
        for space in range(k, weight - 1, -1):
            for cnt in range(1, quantity + 1):
                if space >= cnt:
                    dp[space] = max(dp[space], dp[space - cnt] + value * cnt)

    print(dp[k])

solve()
