def dijkstra(n, computers, dependencies):
    """Find minimum time to complete all parts."""

    # Build adjacency list for dependencies
    graph = [[] for _ in range(n + 1)]  # 1-indexed
    in_degree = [0] * (n + 1)

    for i in range(1, n + 1):
        ki, *deps = map(int, input().split())
        for dep in deps:
            graph[dep].append(i)
            in_degree[i] += 1

    # Topological sort
    top_order = []
    from collections import deque

    q = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            q.append(i)

    while q:
        u = q.popleft()
        top_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Dijkstra's algorithm
    from heapq import heappush, heappop

    # State: (total_time, completed_parts_mask, current_computer)
    # Initially we can start at any computer
    heap = []
    for comp in range(1, 4):
        heappush(heap, (0, 0, comp))  # 0 completed parts, current computer

    # dist[completed_mask][computer] = minimum time
    dist = [[float('inf')] * 4 for _ in range(1 << n)]

    while heap:
        time, mask, comp = heappop(heap)

        # If we've completed all parts, return the time
        if mask == (1 << n) - 1:
            return time

        # If we've already found a better path to this state, skip
        if time > dist[mask][comp]:
            continue

        # Try completing each part
        for i in range(1, n + 1):
            # Check if this part can be completed now
            if not (mask & (1 << (i - 1))) and all(mask & (1 << (dep - 1)) for dep in dependencies[i]):
                # Calculate cost to move to the required computer
                required_comp = computers[i - 1]  # 0-indexed

                # Moving cost
                if comp == required_comp:
                    move_cost = 0
                elif comp == 1 and required_comp == 2:
                    move_cost = 1
                elif comp == 1 and required_comp == 3:
                    move_cost = 2
                elif comp == 2 and required_comp == 1:
                    move_cost = 2
                elif comp == 2 and required_comp == 3:
                    move_cost = 1
                elif comp == 3 and required_comp == 1:
                    move_cost = 1
                elif comp == 3 and required_comp == 2:
                    move_cost = 2

                # Complete the part (1 hour)
                new_time = time + move_cost + 1

                # Update state
                new_mask = mask | (1 << (i - 1))
                heappush(heap, (new_time, new_mask, required_comp))

                # Update distance
                if new_time < dist[new_mask][required_comp]:
                    dist[new_mask][required_comp] = new_time

    return float('inf')

