def solve():
    n, m = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(input().strip())

    stars = []

    # For each cell, try to create a star centered at that cell
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                # Try to create a star centered at (i, j)
                # Find the maximum possible size
                max_size = min(i, n - 1 - i, j, m - 1 - j)

                # Try sizes from max_size down to 1
                for s in range(max_size, 0, -1):
                    # Check if all positions in the cross are '*'
                    covered = True
                    for dx in range(-s, s + 1):
                        for dy in range(-s, s + 1):
                            if abs(dx) + abs(dy) > s:
                                continue
                            x = i + dx
                            y = j + dy
                            if x < 0 or x >= n or y < 0 or y >= m:
                                covered = False
                                break
                            if grid[x][y] != '*':
                                covered = False
                                break
                        if not covered:
                            break

                    if covered:
                        # Add this star
                        stars.append((i, j, s))

                        # Mark all covered positions as covered
                        for dx in range(-s, s + 1):
                            for dy in range(-s, s + 1):
                                if abs(dx) + abs(dy) > s:
                                    continue
                                x = i + dx
                                y = j + dy
                                if 0 <= x < n and 0 <= y < m:
                                    grid[x][y] = '.'  # Mark as covered

                        break

    # Check if all '*' have been covered
    for row in grid:
        if '*' in row:
            print(-1)
            return

    print(len(stars))
    for x, y, s in stars:
        print(x + 1, y + 1, s)  # Convert to 1-indexed

