import sys

def is_zebra(n, a):
    if n == 0:
        return False

    # Find the first stripe
    first_color = a[0]
    first_width = 0

    # Count the width of the first stripe
    for i in range(n):
        if a[i] == first_color:
            first_width += 1
        else:
            break

    # Check if all subsequent stripes have the same width and alternate correctly
    current_color = first_color
    current_width = first_width

    for i in range(first_width, n):
        if a[i] == current_color:
            # Stripe continues
            current_width += 1
        else:
            # New stripe starts
            if current_width != first_width or a[i] == current_color:
                return False
            current_color = a[i]
            current_width = 1

    return True

n = int(sys.stdin.readline())
a = list(map(int, sys.stdin.readline().split()))

if is_zebra(n, a):
    print("YES")
else:
    print("NO")
