import math
from math import factorial

def perm_to_rank(perm, n):
    """Convert permutation to its lexicographical rank"""
    rank = 0
    used = [False] * n
    for i in range(n):
        count = 0
        for j in range(n):
            if not used[j] and perm[i] > j:
                count += 1
        rank += count * factorial(n - i - 1)
        used[perm[i]] = True
    return rank

def rank_to_perm(rank, n):
    """Convert rank back to permutation"""
    perm = [0] * n
    used = [False] * n
    for i in range(n):
        for j in range(n):
            if not used[j]:
                # Try placing j at position i
                temp_rank = 0
                temp_used = used[:]
                temp_perm = perm[:]
                count = 0
                for k in range(n):
                    if not temp_used[k]:
                        for l in range(n):
                            if not temp_used[l] and temp_perm[k] > l:
                                count += 1
                        temp_rank += count * factorial(n - k - 1)
                        temp_used[temp_perm[k]] = True
                if temp_rank == rank:
                    perm[i] = j
                    used[j] = True
                    break
    return perm

n = int(input())
while n > 0:
    p = list(map(int, input().split()))
    q = list(map(int, input().split()))

    ord_p = perm_to_rank(p, n)
    ord_q = perm_to_rank(q, n)

    total_rank = ord_p + ord_q

    result = rank_to_perm(total_rank, n)
    print(' '.join(map(str, result)))

    n = int(input())
