n, m = map(int, input().split())
r, c = map(int, input().split())
x, y = map(int, input().split())

# Convert to 0-indexed
start_row = r - 1
start_col = c - 1

# Read maze
maze = []
for _ in range(n):
    maze.append(input().strip())

# BFS from starting position
from collections import deque
queue = deque([(start_row, start_col, 0, 0)])  # (row, col, left_moves, right_moves)
visited = [[False] * m for _ in range(n)]
visited[start_row][start_col] = True

reachable_cells = 1  # Start cell is always reachable

while queue:
    row, col, left, right = queue.popleft()

    # Try all four directions
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        new_row = row + dr
        new_col = col + dc

        # Check if new position is valid
        if 0 <= new_row < n and 0 <= new_col < m:
            # Check if cell is free
            if maze[new_row][new_col] == ".":
                # Check if we can move there given constraints
                if dc == -1:  # Left move
                    if left < x:
                        if not visited[new_row][new_col]:
                            visited[new_row][new_col] = True
                            queue.append((new_row, new_col, left + 1, right))
                elif dc == 1:  # Right move
                    if right < y:
                        if not visited[new_row][new_col]:
                            visited[new_row][new_col] = True
                            queue.append((new_row, new_col, left, right + 1))
                else:  # Up/down move (no constraint)
                    if not visited[new_row][new_col]:
                        visited[new_row][new_col] = True
                        queue.append((new_row, new_col, left, right))

# After BFS, count all visited cells
for row in range(n):
    for col in range(m):
        if maze[row][col] == "." and visited[row][col]:
            reachable_cells += 1

print(reachable_cells)
