import sys

def solve():
    # Read input
    a = list(map(int, sys.stdin.readline().split()))

    max_score = 0

    # Try each hole as the starting point
    for start in range(14):
        if a[start] == 0:
            continue

        stones = a[start]

        # Calculate score without modifying the array
        score = 0

        # The stones will be distributed to holes in the range [start+1, start+stones]
        # This is a circular range, so we need to handle wrap-around

        # First, calculate how many stones go to each hole
        for i in range(14):
            if i == start:
                continue

            # Does the stone distribution reach hole i?
            # If i > start: we need i - start <= stones
            # If i < start: we need 14 - start + i <= stones

            if (i > start and i - start <= stones) or (i < start and (14 - start + i) <= stones):
                new_count = a[i] + 1
                if new_count % 2 == 0:
                    score += new_count
            else:
                # No stone from the distribution, just use original count
                if a[i] % 2 == 0:
                    score += a[i]

        # The starting hole now has 0 stones, which is even, so add it to the score
        # (since 0 is even)
        if 0 % 2 == 0:
            score += 0

        # Update maximum score
        if score > max_score:
            max_score = score

    print(max_score)

if __name__ == "__main__":
    solve()
