def solve() -> None:
    n, m, k = map(int, input().split())
    matrix = []
    for _ in range(n):
        matrix.append(list(map(int, input().split())))

    # For each row, compute maximum sum for each modulo k
    row_results = []
    for row in matrix:
        max_elements = min(m // 2, len(row))
        # Track maximum sum for each modulo
        mod_sums = {}
        for subset_size in range(max_elements + 1):
            for subset in itertools.combinations(row, subset_size):
                total = sum(subset)
                mod = total % k
                if mod not in mod_sums or total > mod_sums[mod]:
                    mod_sums[mod] = total
        row_results.append(mod_sums)

    # Combine results from all rows
    final_mod_sums = {0: 0}  # Start with 0 sum, divisible by k
    for row_mod_sums in row_results:
        new_mod_sums = {}
        for prev_mod, prev_total in final_mod_sums.items():
            for curr_mod, curr_total in row_mod_sums.items():
