def is_consistent(points):
    """Check if given points can form a consistent line."""
    if len(points) < 2:
        return True

    # Check consistency for all triples
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            for k in range(j + 1, len(points)):
                # Points: (i+1, points[i]), (j+1, points[j]), (k+1, points[k])
                # Check if collinear using cross-multiplication to avoid division
                if (points[j] - points[i]) * (k - i) != (points[k] - points[i]) * (j - i):
                    return False
    return True

n = int(input())
y = list(map(int, input().split()))

# Try all possible lines through point 0 (x=1, y=y[0])
# Check if other points can form a parallel line
