for i in range(n):
    # Points that should be on the line through point 0 and i
    points_on_line0 = []
    for j in range(n):
        if j == 0 or j == i:
            points_on_line0.append(y[j])
        else:
            # Check if point j lies on the line through points 0 and i
            # Slope consistency check using cross-multiplication
            if (y[i] - y[0]) * (j - 0) == (y[j] - y[0]) * (i - 0):
                points_on_line0.append(y[j])

    # Check if points_on_line0 form a consistent line
    if is_consistent(points_on_line0):
        # Remaining points
        remaining_points = [y[k] for k in range(n) if k not in {0, i}]

        # Check if remaining points can form a consistent line
        # and if the two lines are parallel and non-overlapping
        if remaining_points:
            if is_consistent(remaining_points):
                # Check if slopes are equal (parallel)
                # Use cross-multiplication for consistent check
                # Slope of line through points_on_line0
                # Check if all points have same slope
