# dp[i][j] = minimum length for subarray from i to j (inclusive)
dp = [[0] * n for _ in range(n)]

# Base case: single element
for i in range(n):
    dp[i][i] = 1

# Fill dp table for subarrays of length > 1
for length in range(2, n + 1):
    for i in range(n - length + 1):
        j = i + length - 1

        # If first and last elements are equal, try merging
        if a[i] == a[j]:
            # Try all possible splits
            min_len = float('inf')
            for k in range(i, j):
                # If we can merge elements from i to k and k+1 to j
                if a[k] == a[i]:
                    min_len = min(min_len, dp[i][k] + dp[k+1][j] - 1)

            # If we can merge the entire subarray
            if min_len != float('inf'):
                dp[i][j] = min_len
            else:
                # Can't merge, just take minimum of left and right
                dp[i][j] = dp[i][j-1]
        else:
            # Elements not equal, just take minimum of left and right
            dp[i][j] = dp[i][j-1]

print(dp[0][n-1])
