def count_ways(n, m, mod):
    """Count the number of ways to fill the remaining matrix."""
    rows = []
    for _ in range(m):
        rows.append(input().strip())

    # Count column ones
    col_counts = [0] * n
    for i in range(n):
        for j in range(n):
            if rows[i][j] == '1':
                col_counts[j] += 1

    # Check if column counts exceed 2
    for count in col_counts:
        if count > 2:
            return 0

    # Count needed ones in each column
    needed = [2 - count for count in col_counts]

    # Check if needed counts are valid
    for need in needed:
        if need < 0:
            return 0

    # Count the number of ways
    # The formula: product of C((n-m), needed[i]) / (product of (needed[i]!))

    # But we also need to ensure each row has exactly 2 ones

    # Actually, I think the formula is correct
    # Let me implement it

    from math import comb

    total = 1
    for need in needed:
        total = (total * comb((n-m), need)) % mod

    for need in needed:
        total = (total * pow(comb(need, need), mod-2, mod)) % mod

    return total

n, m, mod = map(int, input().split())

