    """Find how many turns Valera makes from (0, 0) to (x, y) along the spiral."""
    if x == 0 and y == 0:
        return 0

    # Count how many complete segments we've done
    turns = 0

    # Keep going until we find the segment that contains (x, y)
    while True:
        # Try to find the segment

        # Right segment: from (n, -n) to (2n+1, -n)
        # For n starting at 0
        found = False

        for n in range(1000):
            # Right segment
            start = (n, -n)
            end = (2 * n + 1, -n)
            if start[0] <= x <= end[0] and start[1] == y:
                turns += n + 1
                return turns

            # Up segment
            start = (2 * n + 1, -n)
            end = (2 * n + 1, n + 1)
            if start[0] == x and start[1] <= y <= end[1]:
                turns += 2 * n + 1
                return turns

            # Left segment
            start = (2 * n + 1, n + 1)
            end = (-2 * n - 1, n + 1)
            if start[1] == y and start[0] >= x >= end[0]:
