def find_longest_match(prefix: str, suffix: str) -> int:
    """Find the length of the longest prefix of `prefix` that matches a suffix of `suffix`"""
    min_len = min(len(prefix), len(suffix))
    for i in range(min_len, 0, -1):
        if prefix[:i] == suffix[-i:]:
            return i
    return 0

