    result = words[0]
    for i in range(1, n):
        # Find the longest prefix of `result` that matches a suffix of `words[i]`
        match_len = find_longest_match(result, words[i])

        # Remove the matching prefix from `words[i]`
        new_word = words[i][match_len:]

        # Concatenate
        result += new_word

    print(result)
