def can_build_tree(n, c):

    # Count how many nodes have ci = 1 (potential leaves)
    leaves = c.count(1)

    # Check if there's a node with ci = n (this must be the root)
    if n not in c:
        return False

    # Count how many internal nodes we have
    internal_nodes = n - leaves

    # We need at least one internal node (unless n = 1)
    if n == 1:
        return leaves == 1
    if internal_nodes == 0:
        return False

    # Create a frequency dictionary for subtree sizes
    freq = {}
    for size in c:
        freq[size] = freq.get(size, 0) + 1

    # We need to check if we can match the requirements
    # For each internal node with subtree size ci, we need two other nodes
    # whose sizes sum to ci - 1

    # We'll use a multiset approach
    from collections import Counter
    multiset = Counter(c)

    # Find the root (the node with subtree size n)
    root_size = n
    multiset[root_size] -= 1

    # Check if we can build the rest of the tree
    for size in range(root_size, 0, -1):
        if size == root_size:
            continue

        count = multiset.get(size, 0)
        if count == 0:
            continue

        # We need two other nodes whose sizes sum to size - 1
        found = False
        for other_size in range(1, size):
            if multiset.get(other_size, 0) >= 2:
                multiset[other_size] -= 2
                found = True
                break
            elif multiset.get(other_size, 0) >= 1:
                # Try combining with another size
                for second_other_size in range(other_size + 1, size):
                    if multiset.get(second_other_size, 0) >= 1:
                        multiset[other_size] -= 1
                        multiset[second_other_size] -= 1
                        found = True
                        break
                if found:
                    break

        if not found:
            return False

    return True

n = int(input())
