def longest_common_subsequence_without_virus(s1, s2, virus):
    """Find the longest common subsequence of s1 and s2 that doesn't contain virus as a substring."""

    # DP[i][j][k] = (length, subsequence) where:
    # i = position in s1
    # j = position in s2
    # k = current state of virus match (0 to len(virus))
    # state k means we have matched the first k characters of virus

    # Initialize DP table
    len_s1, len_s2, len_virus = len(s1), len(s2), len(virus)

    # DP[i][j][k] = (length, subsequence)
    dp = [[[None for _ in range(len_virus + 1)] for _ in range(len_s2 + 1)] for _ in range(len_s1 + 1)]

