    for i in range(len_s1):
        for j in range(len_s2):
            for k in range(len_virus + 1):
                # If we don't take the current character from s1
                if dp[i][j][k] is not None:
                    # Take the character from s2 if it matches
                    if s2[j] == s1[i]:
                        new_k = k
                        if k < len_virus and s1[i] == virus[k]:
