                # If we don't take the current character from s2
                if dp[i][j][k] is not None:
                    # Take the character from s1 if it matches
                    if s1[i] == s2[j]:
                        new_k = k
                        if k < len_virus and s1[i] == virus[k]:
                            new_k += 1
                        # Only keep this state if it doesn't complete the virus
                        if new_k < len_virus:
                            if dp[i+1][j+1][new_k] is None or dp[i+1][j+1][new_k][0] < dp[i][j][k][0] + 1:
                                dp[i+1][j+1][new_k] = (dp[i][j][k][0] + 1, dp[i][j][k][1] + s1[i])
                    # Don't take the character from s1
                    if dp[i+1][j][k] is None or dp[i+1][j][k][0] < dp[i][j][k][0]:
                        dp[i+1][j][k] = (dp[i][j][k][0], dp[i][j][k][1])

    # Find the best result
    max_len = 0
    best_subseq = ""
    for k in range(len_virus + 1):
        if dp[len_s1][len_s2][k] is not None:
            length, subseq = dp[len_s1][len_s2][k]
            # Check if subseq contains virus as a substring
            if virus not in subseq:
                if length > max_len:
                    max_len = length
                    best_subseq = subseq

    return best_subseq if max_len > 0 else "0"

