def solve():
    import sys
    input = sys.stdin.read().split()
    it = iter(input)

    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        a = list(map(int, [next(it) for _ in range(n)]))

        # Map value to list of indices (0-based)
        value_indices = {}
        for idx, val in enumerate(a):
            if val not in value_indices:
                value_indices[val] = []
            value_indices[val].append(idx)

        ans = 0

        # For each value, process all pairs of indices
        for indices in value_indices.values():
            k = len(indices)
            for i in range(k):
                for j in range(i + 1, k):
                    ans += (indices[i] + 1) * (n - indices[j])

        print(ans)

solve()

