def modinv(x, mod):
    """Compute modular inverse using Fermat's little theorem."""
    return pow(x, mod - 2, mod)

def comb(n, k, mod):
    """Compute combination C(n, k) modulo mod."""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n - k:
        k = n - k
    # Compute C(n, k) using multiplicative formula
    res = 1
    for i in range(k):
        res = res * (n - i) % mod
        res = res * modinv(i + 1, mod) % mod
    return res

n, m = map(int, input().split())
