conflicts = []
for i, club in enumerate(clubs):
    if club[2] == club[3]:
        conflicts.append(i)

# If there are conflicts, we need to handle them carefully
# For now, just check if we can find a valid assignment

# Try to assign names
assigned = {}  # Maps short name to club index
possible = True

for i, club in enumerate(clubs):
    option1 = club[2]
    option2 = club[3]

    # If option1 == option2, we only consider it once
    if option1 == option2:
        if option1 in assigned:
            possible = False
            break
        assigned[option1] = i
        continue

    # Check if we can use option1
    can_use_option1 = True
    for j, other in enumerate(clubs):
        if j == i:
            continue
        if other[2] == option1:
            # Other club has same option1 name, cannot use option1
            can_use_option1 = False
            break

    if can_use_option1 and option1 not in assigned:
        assigned[option1] = i
    elif can_use_option1:
        # Cannot use option1 because it's already assigned
        # Check if we can use option2
        if option2 not in assigned:
            assigned[option2] = i
        else:
            possible = False
            break
    else:
        # Cannot use option1, must use option2
        if option2 not in assigned:
            assigned[option2] = i
        else:
            possible = False
            break

if possible:
    print("YES")
    for i in range(n):
        for short_name, idx in assigned.items():
            if idx == i:
                print(short_name)
                break
else:
    print("NO")
