def find_min_newspapers(s1, s2):
    # Map each character to its positions in s1
    char_positions = {}
    for idx, char in enumerate(s1):
        if char not in char_positions:
            char_positions[char] = []
        char_positions[char].append(idx)

    # Check if all characters in s2 exist in s1
    for char in s2:
        if char not in char_positions:
            return -1

    # Track how many times we need to wrap around s1
    count = 1
    current_pos = -1  # Start before the first character

    for char in s2:
        # Find the first position in s1 where this character appears after current_pos
        positions = char_positions[char]
        found = False

        for pos in positions:
            if pos > current_pos:
                current_pos = pos
                found = True
                break

        if not found:
            # Need to wrap around to the next copy of s1
            count += 1
            current_pos = 0
            # Find the first occurrence of this character in the next copy
            for pos in positions:
                if pos >= current_pos:
                    current_pos = pos
                    found = True
                    break

    return count

# Read input
s1 = input().strip()
s2 = input().strip()

# Solve and print result
