import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    likes = list(map(int, data[1:1+n]))

    # Count likes for each photo
    like_count = {}
    for photo in likes:
        like_count[photo] = like_count.get(photo, 0) + 1

    # Find the maximum number of likes
    max_likes = max(like_count.values())

    # Find which photos have the maximum likes
    max_photos = [photo for photo, count in like_count.items() if count == max_likes]

    # For each photo, find when it first reached the max likes
    first_reach_max = {}
    for photo in max_photos:
        count = 0
        for i, like in enumerate(likes):
            if like == photo:
                count += 1
                if count == max_likes:
                    first_reach_max[photo] = i + 1  # 1-indexed position
                    break

    # Find the photo with the earliest first reach of max likes
    winner = min(first_reach_max, key=first_reach_max.get)

    print(winner)

if __name__ == "__main__":
    solve()
"}

