import sys

def count_bit_distances(n):
    """Count the sum of distances between consecutive 1's from the right."""
    bits = []
    for i in range(n.bit_length()):
        if (n >> i) & 1:
            bits.append(i)

    if len(bits) < 2:
        return 0

    # Sum of distances between consecutive 1's from the right
    total = 0
    for i in range(len(bits) - 2, -1, -1):
        total += bits[i+1] - bits[i]
    return total

def solve():
