top_left_black = (0, 0)
initial_black = set()
for i in range(n):
    for j in range(m):
        if (i + j) % 2 == 0:
            initial_black.add((i, j))

# Track which squares get repainted at which minutes
repaint = {square: set() for square in initial_black}
for square in initial_black:
    repaint[square].add(0)

# For each minute, check which squares can be repainted
minute = 1
while True:
    # Find squares that can be repainted at this minute
    to_repaint = set()
    for square in initial_black:
        if minute - 1 in repaint[square]:
            # Check if all four corner-adjacent squares are repainted at minute - 1
            can_repaint = True
            for di, dj in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                ni, nj = square[0] + di, square[1] + dj
                if (ni, nj) not in initial_black or (minute - 1) not in repaint[(ni, nj)]:
                    can_repaint = False
                    break
            if can_repaint:
                to_repaint.add(square)

    if not to_repaint:
        break

    for square in to_repaint:
        repaint[square].add(minute)

    minute += 1

# Count how many squares are painted exactly x times
count = 0
for times in repaint.values():
    if len(times) == x:
        count += 1

print(count)
