from collections import defaultdict

def kmp_failure(virus):
    n = len(virus)
    fail = [0] * n
    j = 0
    for i in range(1, n):
        while j > 0 and virus[i] != virus[j]:
            j = fail[j-1]
        if virus[i] == virus[j]:
            j += 1
            fail[i] = j
        else:
            fail[i] = 0
    return fail

def next_state(k, c, virus, fail):
    # Returns next state after adding char c from state k
    while k > 0 and c != virus[k]:
        k = fail[k-1]
    if c == virus[k]:
        k += 1
    return k

def solve(s1, s2, virus):
    n1, n2 = len(s1), len(s2)
    m = len(virus)

    # DP: dp[i][j][k] = (max_length, prev_state, chosen_char)
    dp = [None] * (n1 + 1)
    for i in range(n1 + 1):
        dp[i] = [None] * (n2 + 1)
        for j in range(n2 + 1):
            dp[i][j] = [None] * (m + 1)

    fail = kmp_failure(virus)

    # Base: dp[0][0][0] = 0, no char taken
    dp[0][0][0] = (0, None, None)

    for i in range(n1):
        for j in range(n2):
            for k in range(m + 1):
                if dp[i][j][k] is None:
                    continue
                length, prev_state, ch = dp[i][j][k]

                # Option 1: take s1[i]
                new_i = i + 1
                new_k = next_state(k, s1[i], virus, fail)
                if new_k != m:  # not full match
                    new_length = length + 1
                    if dp[new_i][j][new_k] is None or new_length > dp[new_i][j][new_k][0]:
                        dp[new_i][j][new_k] = (new_length, (i, j, k), s1[i])

                # Option 2: take s2[j]
                new_j = j + 1
                new_k2 = next_state(k, s2[j], virus, fail)
                if new_k2 != m:
                    new_length = length + 1
                    if dp[i][new_j][new_k2] is None or new_length > dp[i][new_j][new_k2][0]:
                        dp[i][new_j][new_k2] = (new_length, (i, j, k), s2[j])

                # Option 3: don't take either
                if dp[i][j][k] is None:
                    dp[i][j][k] = (length, None, None)

    max_len = 0
    best = None
    for i in range(n1 + 1):
        for j in range(n2 + 1):
            for k in range(m + 1):
                if dp[i][j][k] is not None and dp[i][j][k][0] > max_len:
                    max_len = dp[i][j][k][0]
                    best = dp[i][j][k]

    if max_len == 0:
        return "0"

    # Reconstruct
    res = []
    while best is not None:
        _, prev, ch = best
        if ch is not None:
            res.append(ch)
        best = prev

    return ''.join(reversed(res))

