import sys

def compress_words(words):
    if not words:
        return ""

    result = words[0]

    for i in range(1, len(words)):
        new_word = words[i]

        # Find the longest common prefix/suffix
        overlap = 0

        # Compare suffix of result with prefix of new_word
        while overlap < len(result) and overlap < len(new_word):
            if result[-(overlap + 1)] == new_word[overlap]:
                overlap += 1
            else:
                break

        # Remove the overlapping part from new_word
        new_word = new_word[overlap:]

        # Append to result
        result += new_word

    return result

