n, m, k = map(int, input().split())
matrix = []
for _ in range(n):
    matrix.append(list(map(int, input().split())))

max_choose = m // 2

# dp[i][r] = maximum sum with remainder r after i rows
# Use a list of dictionaries for DP

# Initialize with 0 rows: remainder 0 has sum 0

# For each row, compute all possible sums for choosing 0..max_choose elements
# Then combine with previous DP

dp = [{} for _ in range(n + 1)]
dp[0][0] = 0  # With 0 rows, remainder 0 has sum 0

for i in range(1, n + 1):
    row = matrix[i - 1]

    # Compute all possible sums for this row
    # We'll use a dictionary where key is the number of elements chosen, value is a dictionary of remainders
    row_dp = {}

    # Base case: 0 elements chosen
    row_dp[0] = {0: 0}

    # Try choosing 1..len(row) elements
    for choose in range(1, len(row) + 1):
        row_dp[choose] = {}

        # Try adding each element to combinations with fewer elements
        for j in range(len(row)):
            # We need to add element at position j to combinations with choose-1 elements
            for prev_choose in range(choose - 1, -1, -1):
                if prev_choose in row_dp and j >= prev_choose:
                    for rem, val in row_dp[prev_choose].items():
                        new_sum = val + row[j]
                        new_rem = new_sum % k
                        row_dp[choose][new_rem] = max(row_dp[choose].get(new_rem, -float('inf')), new_sum)

    # Now filter to keep only sums that use at most max_choose elements
    filtered = {}
    for choose in range(0, max_choose + 1):
        for rem, val in row_dp[choose].items():
            filtered[rem] = max(filtered.get(rem, -float('inf')), val)

    # Combine with previous DP
    new_dp = {}
    for prev_remainder, prev_sum in dp[i - 1].items():
        for rem, curr_sum in filtered.items():
            total_sum = prev_sum + curr_sum
            new_remainder = total_sum % k
            new_dp[new_remainder] = max(new_dp.get(new_remainder, -float('inf')), total_sum)

    dp[i] = new_dp

print(dp[n].get(0, 0))
