def solve():
    n = int(input())
    states = list(map(int, input().split()))

    unread_positions = []
    for i, state in enumerate(states):
        if state == 1:
            unread_positions.append(i)

    if not unread_positions:
        print(0)
        return

    # Greedy approach: iterate through the list and count operations
    total_operations = 0
    current_position = 0  # Start at list (position 0)
    in_list = True

    for i in range(n):
        if in_list and states[i] == 1:
            # Open this position
            total_operations += 1
            current_position = i
            in_list = False
        elif not in_list and states[i] == 1:
            # Move to this position from viewing mode
            total_operations += 1
            current_position = i
        elif not in_list and states[i] == 0:
            # Move to next/previous
            if i > current_position:
                total_operations += 1
                current_position = i
            elif i < current_position:
                total_operations += 1
                current_position = i
        elif in_list and states[i] == 0:
            # Already in list, nothing to do
            pass

    # Return to list after finishing
    if not in_list:
        total_operations += 1

    print(total_operations)

solve()
