    if n == 0:
        return ""
    digits = []
    while n > 0:
        digits.append(n % 3)
        n //= 3
    return digits

def from_base_3(digits):
    """Convert base-3 digits (least significant digit first) to decimal."""
    result = 0
    for i, digit in enumerate(digits):
        result += digit * (3 ** i)
    return result

