n, m = map(int, input().split())

# Read numerator set
numerator_set = list(map(int, input().split()))

# Read denominator set
denominator_set = list(map(int, input().split()))

# Function to get prime factorization of a number
def get_prime_factors(x):
    factors = {}
    while x % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        x //= 2
    i = 3
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x //= i
        i += 2
    if x > 1:
        factors[x] = factors.get(x, 0) + 1
    return factors

# Get prime factors for numerator product
numerator_factors = {}
for num in numerator_set:
    factors = get_prime_factors(num)
    for prime, count in factors.items():
        numerator_factors[prime] = numerator_factors.get(prime, 0) + count

# Get prime factors for denominator product
denominator_factors = {}
for den in denominator_set:
    factors = get_prime_factors(den)
    for prime, count in factors.items():
        denominator_factors[prime] = denominator_factors.get(prime, 0) + count

# Compute GCD by taking minimum of corresponding prime powers
common_factors = {}
for prime in numerator_factors:
    if prime in denominator_factors:
        common_factors[prime] = min(numerator_factors[prime], denominator_factors[prime])

# Subtract GCD from numerator and denominator
reduced_numerator_factors = {}
for prime, count in numerator_factors.items():
    if prime in common_factors:
        reduced_numerator_factors[prime] = count - common_factors[prime]
    else:
        reduced_numerator_factors[prime] = count

reduced_denominator_factors = {}
for prime, count in denominator_factors.items():
    if prime in common_factors:
        reduced_denominator_factors[prime] = count - common_factors[prime]
    else:
        reduced_denominator_factors[prime] = count

# Convert factors back to sets of integers
reduced_numerator_set = []
for prime, count in reduced_numerator_factors.items():
    reduced_numerator_set.extend([prime] * count)

reduced_denominator_set = []
for prime, count in reduced_denominator_factors.items():
    reduced_denominator_set.extend([prime] * count)

# Output the result
print(len(reduced_numerator_set), len(reduced_denominator_set))
print(' '.join(map(str, reduced_numerator_set)))
print(' '.join(map(str, reduced_denominator_set)))
