    for j in range(m):
        if grid[i][j] == '*':
            # Check if this '*' is already covered by an existing star
            covered = False
            for (cx, cy, cs) in stars:
                if abs(i - cx) <= cs and abs(j - cy) <= cs:
                    covered = True
                    break

            if not covered:
                # Place a star at (i, j)
                # Need to choose a size s such that the star fits
                # The star of size s at (i, j) must have:
                # i-s >= 0, i+s < n, j-s >= 0, j+s < m
                # So s can be at most min(i, n-1-i, j, m-1-j)
                max_size = min(i, n-1-i, j, m-1-j)
                if max_size == 0:
                    # Can't place a star at this position
                    print(-1)
                    exit()

                # Place a star of size max_size (or any positive size)
                stars.append((i, j, max_size))

print(len(stars))
for x, y, s in stars:
    print(x + 1, y + 1, s)
