    for _ in range(t):
        n, k = map(int, input().split())
        grid = []
        for _ in range(3):
            grid.append(input().strip())

        # Find Philip's starting position
        start_col = 0
        start_row = -1
        for r in range(3):
            if grid[r][0] == 's':
                start_row = r
                break

        # Find train positions
        train_positions = []
        for r in range(3):
            for c in range(n):
                if grid[r][c] != '.' and grid[r][c] != 's':
                    train_positions.append((r, c))

        # Simulate movement
        row = start_row
        col = 0

        while col < n - 1:
            # Move right
            col += 1

            # Check if Philip is in a train's position
            collision = False
            for (r, c) in train_positions:
                if r == row and c == col:
                    collision = True
                    break
            if collision:
                print("NO")
                break

            # Move up/down/stay
            # Try all possible moves
            possible_moves = [(0, 0)]  # stay
            if row > 0:
                possible_moves.append((-1, 0))  # up
            if row < 2:
                possible_moves.append((1, 0))   # down

            found = False
            for dr, dc in possible_moves:
                new_row = row + dr

                # Check collision after moving up/down
                collision = False
                for (r, c) in train_positions:
                    if r == new_row and c == col:
                        collision = True
                        break
                if not collision:
                    row = new_row
                    found = True
                    break

            if not found:
                print("NO")
                break

            # Trains move left 2 cells
            for i in range(len(train_positions)):
                r, c = train_positions[i]
                if c >= 2:
                    train_positions[i] = (r, c - 2)
        else:
            # Successfully reached the end
            print("YES")

