        for r in range(3):
            for c in range(n):
                if grid[r][c] != '.' and grid[r][c] != 's':
                    train_positions.append((r, c))

        # BFS to find path
        from collections import deque
        visited = set()
        queue = deque([(start_row, 0, tuple(train_positions))])
        visited.add((start_row, 0, tuple(train_positions)))

        found = False
        answer = "NO"

        while queue:
            row, col, t_pos = queue.popleft()

            if col == n - 1:
                found = True
                answer = "YES"
                break

            # Move right
            new_col = col + 1

            # Check if Philip can move right
            collision = False
            for (r, c) in t_pos:
                if r == row and c == new_col:
                    collision = True
                    break
            if not collision:
                # Move up/down/stay
                new_row = row
                new_t_pos = list(t_pos)

                for dr, dc in [(0, 0), (-1, 0), (1, 0)]:
                    new_r = row + dr

                    # Check if Philip can move up/down
                    collision = False
                    for (r, c) in t_pos:
                        if r == new_r and c == new_col:
                            collision = True
                            break
                    if not collision:
                        # Move trains left 2 cells
                        new_train_positions = []
                        for r, c in new_t_pos:
                            new_c = c - 2
                            if new_c >= 0:
                                new_train_positions.append((r, new_c))
                            else:
                                new_train_positions.append((r, new_c))

                        # Check if Philip collides with trains after they move
                        collision = False
                        for (r, c) in new_train_positions:
                            if r == new_r and c == new_col:
                                collision = True
                                break
                        if not collision:
                            new_state = (new_r, new_col, tuple(new_train_positions))
                            if new_state not in visited:
                                visited.add(new_state)
                                queue.append(new_state)

        print(answer)

