def reverse_index(pos, k):
    """Reverse the bits of position in the lower k bits"""
    return (pos >> (k + 1)) | ((pos >> (k + 1)) ^ (pos & ((1 << (k + 1)) - 1))) << (k + 1)

def swap_index(pos, k):
    """Swap the bits of position in the lower k bits"""
    return (pos >> (k + 1)) | ((pos >> (k + 1)) ^ (pos & ((1 << (k + 1)) - 1))) << (k + 1)

n, q = map(int, input().split())
array_size = 1 << n
a = list(map(int, input().split()))

# Process queries
for _ in range(q):
    query = input().split()
    if query[0] == "1":  # Replace(x, k)
        x = int(query[1]) - 1  # Convert to 0-indexed
        k = int(query[2])
        a[x] = k
    elif query[0] == "2":  # Reverse(k)
        k = int(query[1])
        # Apply Reverse(k) operation to all positions
        # We need to calculate the new position for each element
        for i in range(array_size):
            # Get the new position after Reverse(k)
            new_pos = reverse_index(i, k)
            # Update the array
            a[new_pos] = a[i]
    elif query[0] == "3":  # Swap(k)
        k = int(query[1])
        # Apply Swap(k) operation to all positions
        for i in range(array_size):
            # Get the new position after Swap(k)
            new_pos = swap_index(i, k)
            # Update the array
            a[new_pos] = a[i]
    elif query[0] == "4":  # Sum(l, r)
        l = int(query[1]) - 1  # Convert to 0-indexed
        r = int(query[2]) - 1
        result = sum(a[l:r+1])
        print(result)
