import sys
from collections import defaultdict, deque

def main():
    data = sys.stdin.read().strip().split('\n')
    idx = 0

    # Skip empty lines
    while idx < len(data) and data[idx] == '':
        idx += 1

    if idx >= len(data):
        return

    n = int(data[idx])
    idx += 1

    # Parse projects
    projects = {}
    polycarp_name, polycarp_version = None, None

    for _ in range(n):
        # Skip empty lines
        while idx < len(data) and data[idx] == '':
            idx += 1

        if idx >= len(data):
            break

        name, version = data[idx].split()
        idx += 1
        version = int(version)

        # Skip empty lines
        while idx < len(data) and data[idx] == '':
            idx += 1

        if idx >= len(data):
            break

        dep_count = int(data[idx])
        idx += 1

        # Build graph
        graph = defaultdict(list)
        for _ in range(dep_count):
            # Skip empty lines
            while idx < len(data) and data[idx] == '':
                idx += 1

            if idx >= len(data):
                break

            dep_name, dep_version = data[idx].split()
            idx += 1
            dep_version = int(dep_version)
            graph[(name, version)].append((dep_name, dep_version))

        # Keep track of Polycarp's project
        if _ == 0:
            polycarp_name, polycarp_version = name, version

        projects[(name, version)] = (name, version)

    # Find all projects reachable from Polycarp's project
    reachable = set()
    visited = set()
    queue = deque([(polycarp_name, polycarp_version)])

    while queue:
        proj = queue.popleft()
        if proj in visited:
            continue

        visited.add(proj)
        reachable.add(proj)

        for neighbor in graph[proj]:
            queue.append(neighbor)

    # For each unique name, find the best version
    name_to_best = {}
    for proj in reachable:
        name, version = proj

        # Distance from Polycarp's project
        dist = abs(version - polycarp_version)

        if name not in name_to_best:
            name_to_best[name] = (dist, -version, version, name, version)
        else:
            curr_dist, curr_neg_version, curr_version, curr_name, curr_ver = name_to_best[name]

            if dist < curr_dist:
                name_to_best[name] = (dist, -version, version, name, version)
            elif dist == curr_dist:
                if -version > curr_neg_version:
                    name_to_best[name] = (dist, -version, version, name, version)

    # Output in lexicographical order
    for name, (dist, neg_version, version, _, _) in sorted(name_to_best.items()):
        print(f"{version}")

if __name__ == "__main__":
    main()
