    def get_node(i):
        if i == 0:
            return (x0, y0)
        # Calculate x_i
        ax_pow = pow(ax, i)
        x = ax_pow * x0 + bx * (ax_pow - 1) // (ax - 1)
        # Calculate y_i
        ay_pow = pow(ay, i)
        y = ay_pow * y0 + by * (ay_pow - 1) // (ay - 1)
        return (x, y)

