def solve():
    n, q = map(int, input().split())
    size = 1 << n
    a = list(map(int, input().split()))

    # Fenwick tree for range sums
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, idx, delta):
            # Add delta to index idx (1-indexed)
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            # Sum from 1 to idx
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

        def range_query(self, l, r):
            # Sum from l to r
            return self.query(r) - self.query(l - 1)

        def range_update(self, l, r, delta):
            # Add delta to range [l, r]
            self.update(l, delta)
            self.update(r + 1, -delta)

    ft = FenwickTree(size)

    # Build Fenwick tree from array
    for i in range(size):
        ft.update(i + 1, a[i])

    # Process queries
    for _ in range(q):
        query = input().split()
        if query[0] == '1':  # Replace(x, k)
            x = int(query[1])
            k = int(query[2])
            delta = k - a[x - 1]
            a[x - 1] = k
            ft.range_update(x, x, delta)
        elif query[0] == '2':  # Reverse(k)
            k = int(query[1])
            block_size = 1 << (k + 1)
            for i in range(1, size, block_size):
                l = i
                r = i + block_size - 1
                if r > size:
                    r = size
                # Reverse subarray [l, r]
                for j in range(l, r + 1):
                    ft.range_update(j, j, a[j - 1] - a[r - (j - l) + 1 - 1])
                    a[j - 1], a[r - (j - l) + 1 - 1] = a[r - (j - l) + 1 - 1], a[j - 1]
        elif query[0] == '3':  # Swap(k)
            k = int(query[1])
            block_size = 1 << (k + 1)
            for i in range(1, size, block_size * 2):
                l1 = i
                r1 = i + block_size - 1
                l2 = i + block_size
                r2 = i + 2 * block_size - 1
                if r2 > size:
                    r2 = size
                # Swap subarrays [l1, r1] and [l2, r2]
