n = int(input())
clubs = []
for _ in range(n):
    team, hometown = input().split()
    opt1 = team[:3]
    opt2 = team[:2] + hometown[0]
    clubs.append((team, hometown, opt1, opt2))

# Group by Option 1 name
from collections import defaultdict
option1_groups = defaultdict(list)
for i, (team, hometown, opt1, opt2) in enumerate(clubs):
    option1_groups[opt1].append((i, team, hometown, opt1, opt2))

# Check if it's possible
possible = True
assignment = [None] * n
option2_set = set()

# Process groups with multiple clubs first (all must use Option 2)
for opt1, group in option1_groups.items():
    if len(group) > 1:
        # All clubs in this group must use Option 2
        # Check if all Option 2 names are distinct
        for idx, team, hometown, _, opt2 in group:
            if opt2 in option2_set:
                possible = False
                break
            option2_set.add(opt2)
            assignment[idx] = opt2
        if not possible:
            break

if not possible:
    print("NO")
else:
    # Process groups with single club
    # For each single club, decide whether to use Option 1 or Option 2
    # Prefer Option 1 if it doesn't conflict with any existing assignment
    for opt1, group in option1_groups.items():
        if len(group) == 1:
            idx, team, hometown, _, opt1 = group[0]
            # Check if Option 1 is available
            if opt1 not in option2_set and opt1 not in assignment:
                assignment[idx] = opt1
            else:
                # Need to use Option 2
                opt2 = team[:2] + hometown[0]
                if opt2 in option2_set or opt2 in assignment:
                    possible = False
                    break
                assignment[idx] = opt2

    if not possible:
        print("NO")
    else:
        # Check if all short names are distinct
        if len(set(assignment)) == n:
            print("YES")
            for name in assignment:
                print(name)
        else:
            print("NO")
