def solve():
    n, m, k = map(int, input().split())

    # Read planets
    planets = []
    for _ in range(n):
        name = input().strip()
        planet = {
            'name': name,
            'items': []
        }

        for _ in range(m):
            a, b, c = map(int, input().split())
            planet['items'].append((a, b, c))  # (buy_price, sell_price, max_available)

        planets.append(planet)

    max_profit = 0

    # Try all pairs of planets (buy on planet A, sell on planet B)
    for i in range(n):
        for j in range(n):
            if i == j:
                continue  # Can't buy and sell on the same planet

            # Calculate profit for each item type
            buy_planet = planets[i]
            sell_planet = planets[j]

            # Build list of profitable items
            items = []
            for buy_price, sell_price, max_available in buy_planet['items']:
                if sell_price > buy_price:  # Profitable
                    # We can buy up to min(max_available, k) items of this type
                    items.append((1, sell_price - buy_price, min(max_available, k)))

            # Solve unbounded knapsack with capacity k
            dp = [0] * (k + 1)

            for weight, value, count in items:
                # For each capacity from weight to k
                for cap in range(weight, k + 1):
                    # Try taking t items where t ranges from 1 to min(count, cap - weight + 1)
                    for t in range(1, min(count, cap - weight + 1) + 1):
                        if dp[cap - t * weight] + t * value > dp[cap]:
                            dp[cap] = dp[cap - t * weight] + t * value

            max_profit = max(max_profit, dp[k])

    print(max_profit)

solve()
