def solve():
    n = int(input())
    piles = []
    for _ in range(n):
        parts = list(map(int, input().split()))
        si = parts[0]
        cards = parts[1:1+si]
        # Store as tuple of tuples for hashability
        piles.append(tuple(cards))

    # dp[i][j][turn] = (ciel_score, jiro_score) when we have piles[i:j+1] remaining and it's turn's turn
    # turn: 0 for Ciel, 1 for Jiro

    # We'll use a memoization approach
    memo = {}

    def game(piles, turn):
        # Convert piles to a tuple for hashability
        state = tuple(piles)
        if state in memo:
            return memo[state]

        if all(len(pile) == 0 for pile in piles):
            return (0, 0)

        best_ciel = 0
        best_jiro = 0

        # Current player's turn
        if turn == 0:
            # Ciel's turn: take from top of any non-empty pile
            for i in range(len(piles)):
                if len(piles[i]) > 0:
                    # Create new state by taking from top of pile i
                    new_piles = [pile[:] for pile in piles]
                    new_piles[i] = new_piles[i][1:]  # Remove the first element
                    c, j = game(tuple(new_piles), 1)
                    c += piles[i][0]
                    if c > best_ciel:
                        best_ciel = c
                        best_jiro = j
            memo[state] = (best_ciel, best_jiro)
            return (best_ciel, best_jiro)
        else:
            # Jiro's turn: take from bottom of any non-empty pile
            for i in range(len(piles)):
                if len(piles[i]) > 0:
                    # Create new state by taking from bottom of pile i
                    new_piles = [pile[:] for pile in piles]
                    new_piles[i] = new_piles[i][:-1]  # Remove the last element
                    c, j = game(tuple(new_piles), 0)
                    j += piles[i][-1]
                    if j > best_jiro:
                        best_ciel = c
                        best_jiro = j
            memo[state] = (best_ciel, best_jiro)
            return (best_ciel, best_jiro)

    result = game(tuple(piles), 0)
    print(result[0], result[1])

solve()

