    r, c = map(int, input().split())
    r -= 1  # 0-indexed
    c -= 1

    # dp[i][j] = expected score starting from (i, j)
    dp = [[0] * m for _ in range(n)]

    # Sort positions by value
    positions = []
    for i in range(n):
        for j in range(m):
            positions.append((a[i][j], i, j))

    # Sort by value (largest first)
    positions.sort(reverse=True)

    # For each value, store list of positions
    from collections import defaultdict
    pos_by_val = defaultdict(list)
    for val, i, j in positions:
        pos_by_val[val].append((i, j))

    # For each value in decreasing order, calculate dp
    for val in sorted(pos_by_val.keys(), reverse=True):
        for i, j in pos_by_val[val]:
            # Find all positions with strictly smaller values
            smaller_positions = []
            for v in sorted(pos_by_val.keys()):
                if v < val:
                    smaller_positions.extend(pos_by_val[v])

            if not smaller_positions:
                dp[i][j] = 0
            else:
                # Calculate average of (distance^2 + dp[new_i][new_j])
                total = 0
                cnt = 0
                for ni, nj in smaller_positions:
                    dist2 = (i - ni) ** 2 + (j - nj) ** 2
                    total = (total + dist2 + dp[ni][nj]) % MOD
                    cnt += 1
                dp[i][j] = total * pow(cnt, MOD - 2, MOD) % MOD

    print(dp[r][c])

