from collections import deque

def solve():
    n, m = map(int, input().split())
    r, c = map(int, input().split())
    x, y = map(int, input().split())
    labyrinth = [input().strip() for _ in range(n)]

    # Convert to 0-indexed
    r -= 1
c -= 1

    # BFS to find reachable cells, tracking left/right moves
    visited = [[[-1, -1] for _ in range(m)] for _ in range(n)]
    queue = deque([(r, c)])
    visited[r][c] = [0, 0]

    while queue:
        i, j = queue.popleft()
        left_moves, right_moves = visited[i][j]

        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj

            if 0 <= ni < n and 0 <= nj < m and labyrinth[ni][nj] == '.':
                if visited[ni][nj][0] == -1:
                    # Can move
                    if dj == -1:
                        # Moving left
                        if left_moves + 1 <= x:
                            visited[ni][nj] = [left_moves + 1, right_moves]
                            queue.append((ni, nj))
                    elif dj == 1:
                        # Moving right
                        if right_moves + 1 <= y:
                            visited[ni][nj] = [left_moves, right_moves + 1]
                            queue.append((ni, nj))
                    else:
                        # Moving up/down (no move cost)
                        visited[ni][nj] = [left_moves, right_moves]
                        queue.append((ni, nj))

    count = 0
    for i in range(n):
        for j in range(m):
            if visited[i][j][0] != -1:
                count += 1

    print(count)

solve()
