def max_xor_pair_trie(arr):
    """Find the maximum XOR of any two distinct elements using a trie."""
    # Function to insert a number into the trie
    def insert(num):
        node = root
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            if not node[bit]:
                node[bit] = {}
            node = node[bit]

    # Function to query maximum XOR with a given number
    def query(num):
        node = root
        max_xor = 0
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            toggled_bit = 1 - bit
            if toggled_bit in node:
                max_xor |= (1 << i)
                node = node[toggled_bit]
            else:
                node = node[bit]
        return max_xor

    # Build trie
    root = {}
    for num in arr:
        insert(num)

    # Find maximum XOR
    max_xor = 0
    for num in arr:
        max_xor = max(max_xor, query(num))

    return max_xor

n = int(input())
