def is_palindrome(s):
    return s == s[::-1]

def max_k_palindrome(s):
    if len(s) == 1:
        return 1  # 1-palindrome

    # Check if it's a 1-palindrome
    if not is_palindrome(s):
        return 0

    # Check if it's a k-palindrome for k > 1
    max_k = 1
    n = len(s)
    half_len = n // 2

    # Check if it's a 2-palindrome
    left_half = s[:half_len]
    right_half = s[-half_len:]
    if is_palindrome(left_half) and is_palindrome(right_half) and left_half == right_half:
        max_k = 2

    # Check higher k values recursively
    if max_k > 1:
        # Check if left half is also a (max_k-1)-palindrome
        if is_palindrome(left_half) and max_k_palindrome(left_half) >= max_k - 1:
            # Check if right half is also a (max_k-1)-palindrome
            if is_palindrome(right_half) and max_k_palindrome(right_half) >= max_k - 1:
                max_k += 1

    return max_k


def solve():
    s = input().strip()
    n = len(s)
    result = [0] * n

    # Check all substrings
    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            k = max_k_palindrome(substr)
            if k <= n:
                result[k-1] += 1  # 1-indexed

    print(' '.join(map(str, result)))

