import sys

def compute_prefix(s):
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i-1]
        while j > 0 and s[i] != s[j]:
            j = pi[j-1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    words = data[1:]  # data[0] is n
    n = int(data[0])
    if n == 0:
        return
    result = words[0]
    for word in words[1:]:
        # Compute maximum overlap between result and word
        s = result + '#' + word
        pi = compute_prefix(s)
        k = pi[-1]  # overlap length
        if k > 0:
            result += word[k:]
        else:
            result += word
    print(result)

if __name__ == "__main__":
    main()
"}

