import sys
from collections import defaultdict

def build_failure(virus):
    fail = [0] * len(virus)
    for i in range(1, len(virus)):
        j = fail[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = fail[j-1]
        if virus[i] == virus[j]:
            j += 1
        fail[i] = j
    return fail

def kmp_state(virus, fail, state, char):
    # state is index in virus
    # returns next state after char
    if state == len(virus):
        return len(virus)  # if already in state len(virus), still len(virus)
    while state > 0 and virus[state] != char:
        state = fail[state-1]
    if virus[state] == char:
        state += 1
    return state

def solve():
    s1 = sys.stdin.readline().strip()
    s2 = sys.stdin.readline().strip()
    virus = sys.stdin.readline().strip()

    n, m, L = len(s1), len(s2), len(virus)

    # DP[i][j][k] = (length, i', j', char_used)
    # Actually we'll use a 3D array for length and a 3D array for reconstruction
    # length_dp[i][j][k] = max length
    # path_dp[i][j][k] = tuple (i', j', k', char)
    length_dp = [[[ -1 for _ in range(L+1)] for _ in range(m+1)] for _ in range(n+1)]
    path_dp = [[[None for _ in range(L+1)] for _ in range(m+1)] for _ in range(n+1)]

    # base case
    length_dp[0][0][0] = 0
    path_dp[0][0][0] = (-1, -1, -1, None)

    for i in range(n):
        for j in range(m):
            for k in range(L+1):
                if length_dp[i][j][k] == -1:
                    continue
                l = length_dp[i][j][k]

                # Option 1: Take s1[i] if it matches s2[j]
                if i < n and j < m and s1[i] == s2[j]:
                    new_i = i + 1
                    new_j = j + 1
                    new_k = kmp_state(virus, build_failure(virus), k, s1[i])
                    if new_k <= L:
                        if length_dp[new_i][new_j][new_k] < l + 1:
                            length_dp[new_i][new_j][new_k] = l + 1
                            path_dp[new_i][new_j][new_k] = (i, j, k, s1[i])

                # Option 2: Skip s1[i]
                if i < n:
                    new_i = i + 1
                    if length_dp[new_i][j][k] < l:
                        length_dp[new_i][j][k] = l
                        path_dp[new_i][j][k] = (i, j, k, None)

                # Option 3: Skip s2[j]
                if j < m:
                    new_j = j + 1
                    if length_dp[i][new_j][k] < l:
                        length_dp[i][new_j][k] = l
                        path_dp[i][new_j][k] = (i, j, k, None)

    # Find max length and state
    max_len = -1
    best_i, best_j, best_k = 0, 0, 0
    for i in range(n+1):
        for j in range(m+1):
            for k in range(L+1):
                if length_dp[i][j][k] > max_len:
                    max_len = length_dp[i][j][k]
                    best_i, best_j, best_k = i, j, k

    if max_len == 0:
        print(0)
        return

    # Reconstruct path from best_i, best_j, best_k
    path = []
    i, j, k = best_i, best_j, best_k
    while True:
        if i == 0 and j == 0 and k == 0:
            break
        if path_dp[i][j][k] is None:
            break
        pi, pj, pk, char = path_dp[i][j][k]
        if char is not None:
            path.append(char)
        i, j, k = pi, pj, pk

    path.reverse()
    print(''.join(path))

if __name__ == '__main__':
    solve()
"}

