def solve() -> None:
    n = int(input())

    # Compute factorial
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Compute 2^(n-1) modulo MOD
    power_of_two = pow(2, n - 1, MOD)

    # Answer is cyclic permutations = n! - 2^{n-1}
    answer = (fact[n] - power_of_two) % MOD

    print(answer)

if __name__ == "__main__":
    solve()
