def modinv(x, mod):
    return pow(x, mod - 2, mod)

def solve():
    n, m = map(int, input().split())
    a = []
    for _ in range(n):
        a.append(list(map(int, input().split())))
    r, c = map(int, input().split())
    r -= 1  # 0-indexed
    c -= 1

    # List of (value, row, col)
    positions = []
    for i in range(n):
        for j in range(m):
            positions.append((a[i][j], i, j))

    # Sort by value
    positions.sort()

    # DP table
    dp = [[0] * m for _ in range(n)]

    # Process in increasing order of value
    for val, i, j in positions:
        # Find all positions with smaller values
        count = 0
        total = 0
        for x in range(n):
            for y in range(m):
                if a[x][y] < val:
                    dx = i - x
                    dy = j - y
                    score = (dx * dx + dy * dy) % MOD
                    total = (total + score + dp[x][y]) % MOD
                    count += 1

        if count > 0:
            dp[i][j] = total * modinv(count, MOD) % MOD

    print(dp[r][c])

solve()
